(function(){'use strict';
var BOUNDS_KEY='welog-direct-split-bounds-v2', STICKER_KEY='welog-direct-stickers-v1';
function read(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}
function layoutEditing(){return document.body.classList.contains('welog-layout-editing')||!!document.querySelector('.welog-layout-hud:not([hidden])')}
function removeOldCropPanel(){document.querySelectorAll('.welog-split-area-control').forEach(function(n){n.remove()})}

/* Split-image "bounds" are layout footprint only. They must never crop or scale the artwork. */
function ensureBounds(){removeOldCropPanel();var center=document.querySelector('#sheet .center'),split=center&&center.querySelector('.pair-split');if(!center||!split)return;
  /* Undo the old visual crop completely. */
  split.style.removeProperty('clip-path');split.removeAttribute('data-direct-crop');
  center.style.position='relative';center.style.overflow='visible';split.style.overflow='visible';
  var stored=read(BOUNDS_KEY,null),vr=split.getBoundingClientRect();
  if(!stored||!stored.visualW){stored={w:Math.round(vr.width||360),h:Math.round(vr.height||450),visualW:Math.round(vr.width||360),visualH:Math.round(vr.height||450)}}
  stored.w=Math.max(80,+stored.w||stored.visualW);stored.h=Math.max(80,+stored.h||stored.visualH);write(BOUNDS_KEY,stored);
  var spacer=center.querySelector('.direct-center-footprint-spacer');if(!spacer){spacer=document.createElement('div');spacer.className='direct-center-footprint-spacer';split.insertAdjacentElement('beforebegin',spacer)}
  spacer.style.width=stored.w+'px';spacer.style.height=stored.h+'px';
  /* Artwork keeps its own original size and is centered over the adjustable footprint. */
  split.style.position='absolute';split.style.left='50%';split.style.top='50%';split.style.width=stored.visualW+'px';split.style.height=stored.visualH+'px';split.style.maxWidth='none';split.style.minHeight='0';split.style.transform='translate(-50%,-50%)';split.style.margin='0';
  syncBoundsHandles(center,spacer,stored)
}
function syncBoundsHandles(center,spacer,stored){var old=center.querySelector('.direct-bounds-ui');if(!layoutEditing()){if(old)old.remove();return}if(old)return;var ui=document.createElement('div');ui.className='direct-bounds-ui';ui.innerHTML='<b>중앙 이미지 영향 범위</b><i data-edge="t"></i><i data-edge="r"></i><i data-edge="b"></i><i data-edge="l"></i><i data-corner="br"></i>';center.appendChild(ui);
 function place(){var cr=center.getBoundingClientRect(),sr=spacer.getBoundingClientRect();ui.style.left=(sr.left-cr.left)+'px';ui.style.top=(sr.top-cr.top)+'px';ui.style.width=sr.width+'px';ui.style.height=sr.height+'px'}place();var start=null;
 ui.addEventListener('pointerdown',function(e){var h=e.target.closest('[data-edge],[data-corner]');if(!h)return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();var s=read(BOUNDS_KEY,stored);start={edge:h.dataset.edge||h.dataset.corner,x:e.clientX,y:e.clientY,w:+s.w,h:+s.h};h.setPointerCapture&&h.setPointerCapture(e.pointerId)},true);
 ui.addEventListener('pointermove',function(e){if(!start)return;e.preventDefault();e.stopPropagation();var dx=e.clientX-start.x,dy=e.clientY-start.y,s=read(BOUNDS_KEY,stored);if(start.edge==='l'||start.edge==='r'||start.edge==='br')s.w=Math.max(80,start.w+(start.edge==='l'?-2*dx:2*dx));if(start.edge==='t'||start.edge==='b'||start.edge==='br')s.h=Math.max(80,start.h+(start.edge==='t'?-2*dy:2*dy));write(BOUNDS_KEY,s);spacer.style.width=s.w+'px';spacer.style.height=s.h+'px';place();window.dispatchEvent(new Event('resize'))},true);
 ui.addEventListener('pointerup',function(e){if(start){start=null;e.stopPropagation()}},true)
}
function queueBounds(){setTimeout(ensureBounds,20)}

function stickerLayer(){var sheet=document.getElementById('sheet');if(!sheet)return null;var l=sheet.querySelector('.direct-sticker-layer');if(!l){l=document.createElement('div');l.className='direct-sticker-layer';sheet.appendChild(l)}return l}
function getStickers(){return read(STICKER_KEY,[])}function saveStickers(v){write(STICKER_KEY,v)}
function normalizeSticker(s){return{src:s.src,x:isFinite(+s.x)?+s.x:50,y:isFinite(+s.y)?+s.y:50,w:isFinite(+s.w)?+s.w:120,rot:isFinite(+s.rot)?+s.rot:0,locked:!!s.locked}}
function renderStickers(){var layer=stickerLayer();if(!layer)return;var arr=getStickers().map(normalizeSticker);saveStickers(arr);layer.innerHTML='';arr.forEach(function(s,i){var w=document.createElement('div');w.className='direct-sticker'+(s.locked?' is-locked':'');w.dataset.i=i;w.tabIndex=0;w.style.left=s.x+'%';w.style.top=s.y+'%';w.style.width=s.w+'px';w.style.transform='translate(-50%,-50%) rotate('+s.rot+'deg)';w.innerHTML='<img draggable="false"><div class="st-toolbar"><button type="button" class="st-lock">'+(s.locked?'🔒':'🔓')+'</button><label>크기 <input class="st-size" type="range" min="20" max="600" value="'+Math.round(s.w)+'"></label><label>회전 <input class="st-rot" type="range" min="-180" max="180" value="'+Math.round(s.rot)+'"></label><button type="button" class="st-del">×</button></div><i class="st-resize"></i><i class="st-rotate"></i>';w.querySelector('img').src=s.src;layer.appendChild(w)});bindStickerGestures(layer)}
function bindStickerGestures(layer){layer.querySelectorAll('.direct-sticker').forEach(function(w){var i=+w.dataset.i,mode='',sx=0,sy=0,base=null,pid=null;function update(s){w.style.left=s.x+'%';w.style.top=s.y+'%';w.style.width=s.w+'px';w.style.transform='translate(-50%,-50%) rotate('+s.rot+'deg)'}
w.addEventListener('pointerdown',function(e){if(e.target.closest('.st-toolbar'))return;var arr=getStickers();if(!arr[i]||arr[i].locked)return;base=normalizeSticker(arr[i]);sx=e.clientX;sy=e.clientY;pid=e.pointerId;mode=e.target.closest('.st-resize')?'resize':e.target.closest('.st-rotate')?'rotate':'move';e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();w.setPointerCapture&&w.setPointerCapture(pid)},true);
w.addEventListener('pointermove',function(e){if(!mode||e.pointerId!==pid)return;var arr=getStickers(),s=normalizeSticker(arr[i]),r=document.getElementById('sheet').getBoundingClientRect(),dx=e.clientX-sx,dy=e.clientY-sy;if(mode==='move'){s.x=Math.max(0,Math.min(100,base.x+dx/r.width*100));s.y=Math.max(0,Math.min(100,base.y+dy/r.height*100))}else if(mode==='resize')s.w=Math.max(20,Math.min(600,base.w+dx));else{var wr=w.getBoundingClientRect(),cx=wr.left+wr.width/2,cy=wr.top+wr.height/2;s.rot=Math.atan2(e.clientY-cy,e.clientX-cx)*180/Math.PI}arr[i]=s;saveStickers(arr);update(s);e.preventDefault();e.stopPropagation()},true);w.addEventListener('pointerup',function(){mode='';pid=null},true);w.addEventListener('pointercancel',function(){mode='';pid=null},true);
w.querySelector('.st-del').onclick=function(e){e.stopPropagation();var a=getStickers();a.splice(i,1);saveStickers(a);renderStickers()};w.querySelector('.st-lock').onclick=function(e){e.stopPropagation();var a=getStickers();a[i]=normalizeSticker(a[i]);a[i].locked=!a[i].locked;saveStickers(a);renderStickers()};w.querySelector('.st-size').oninput=function(){var a=getStickers();if(a[i].locked)return;a[i]=normalizeSticker(a[i]);a[i].w=+this.value;saveStickers(a);update(a[i])};w.querySelector('.st-rot').oninput=function(){var a=getStickers();if(a[i].locked)return;a[i]=normalizeSticker(a[i]);a[i].rot=+this.value;saveStickers(a);update(a[i])}})}
function hookStickerUploads(){document.addEventListener('change',function(e){var inp=e.target;if(!inp.matches('[data-sticker-upload]')||!inp.files||!inp.files[0])return;var r=new FileReader();r.onload=function(){var a=getStickers();a.push({src:r.result,x:50,y:50,w:120,rot:0,locked:false});saveStickers(a);renderStickers();inp.value=''};r.readAsDataURL(inp.files[0])},true);document.addEventListener('click',function(e){var b=e.target.closest('[data-sticker-add]');if(!b)return;setTimeout(function(){var img=document.querySelectorAll('.sticker-gallery img')[+b.dataset.stickerAdd];if(!img)return;var a=getStickers();a.push({src:img.src,x:50,y:50,w:120,rot:0,locked:false});saveStickers(a);renderStickers()},0)},true)}
function boot(){var s=document.getElementById('sheet');if(!s)return;hookStickerUploads();ensureBounds();renderStickers();new MutationObserver(queueBounds).observe(document.body,{attributes:true,attributeFilter:['class']});document.addEventListener('click',queueBounds,true);document.addEventListener('input',function(e){if(e.target.closest&&e.target.closest('.direct-sticker'))return;queueBounds()},true)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();